import { test, expect } from '@playwright/test';

test.describe('Popover Toggle Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/popover-toggle');
  });

  test('should open popover when button is clicked', async ({ page }) => {
    // Verify popover is initially closed
    const popover = page.getByRole('region', { name: /popover/i });
    await expect(popover).not.toBeVisible();

    // Click the toggle button
    const toggleButton = page.getByRole('button', { name: /toggle popover/i });
    await toggleButton.click();

    // Verify popover is now visible
    await expect(popover).toBeVisible();

    // Verify popover content is displayed
    const popoverContent = page.getByText(/popover content/i);
    await expect(popoverContent).toBeVisible();

    // Verify popover has focus
    await expect(popover).toHaveFocus();
  });

  test('should close popover when button is clicked again', async ({ page }) => {
    // Open popover by clicking the toggle button
    const toggleButton = page.getByRole('button', { name: /toggle popover/i });
    await toggleButton.click();

    // Verify popover is visible
    const popover = page.getByRole('region', { name: /popover/i });
    await expect(popover).toBeVisible();

    // Click the toggle button again to close
    await toggleButton.click();

    // Verify popover is no longer visible
    await expect(popover).not.toBeVisible();

    // Verify popover content is not displayed
    const popoverContent = page.getByText(/popover content/i);
    await expect(popoverContent).not.toBeVisible();

    // Verify button is still enabled
    await expect(toggleButton).toBeEnabled();
  });
});
